"""Qwen integration using the tested dense FP32 reference adapter."""

import hashlib
import uuid
from pathlib import Path

import torch
from torch import nn

from .adapters import ControlledLinear
from .initialization import Decomposition, decompose

CONDITIONS = {
    "A-S": ("additive", "spectral"),
    "A-R": ("additive", "random"),
    "D-S": ("detached", "spectral"),
    "D-R": ("detached", "random"),
    "E-S": ("exact", "spectral"),
    "E-R": ("exact", "random"),
    "L0": ("additive", "standard"),
    "D0": ("detached", "standard"),
}


def layer_seed(seed: int, name: str) -> int:
    return int.from_bytes(hashlib.sha256(f"{seed}:init:{name}".encode()).digest()[:8], "little") % (
        2**63 - 1
    )


class ModelLinear(ControlledLinear):
    def forward(self, inputs):
        # Preserve FP32 adapter/norm arithmetic even in a BF16 transformer.
        with torch.autocast(device_type=inputs.device.type, enabled=False):
            output = super().forward(inputs)
        return output.to(inputs.dtype)


@torch.no_grad()
def factor_spectrum_errors(b, a, expected):
    """Measure actual FP32 factors independently of CUDA's SVD measurement path."""
    reference = expected.detach().to(device="cpu", dtype=torch.float64)
    errors = []
    for factor in (b, a):
        values = torch.linalg.svdvals(factor.detach().to(device="cpu", dtype=torch.float64))
        errors.append(float(((values - reference).abs() / reference.clamp_min(1e-12)).max()))
    return errors


def insert_adapters(
    model,
    condition: str,
    rank: int,
    gamma: float,
    seed: int,
    targets: list[str],
    cache_dir: Path | None = None,
) -> dict:
    rule, initialization = CONDITIONS[condition]
    model.requires_grad_(False)
    names = [
        name
        for name, layer in model.named_modules()
        if isinstance(layer, nn.Linear) and name.rsplit(".", 1)[-1] in targets
    ]
    if not names or set(targets) != {name.rsplit(".", 1)[-1] for name in names}:
        raise ValueError("adapter targets are missing from this model")
    metadata = {}
    for name in names:
        original = model.get_submodule(name)
        weight = original.weight.detach().float()
        weight_hash = hashlib.sha256(weight.cpu().numpy().tobytes()).hexdigest()
        svd = None
        if initialization != "standard":
            # Never reuse decompositions made by the old CUDA default driver.
            method = "gesvd" if weight.device.type == "cuda" else "lapack"
            cache = (
                None if cache_dir is None else cache_dir / f"{weight_hash}-r{rank}-{method}-v2.pt"
            )
            if cache is not None and cache.exists():
                saved = torch.load(cache, map_location=weight.device, weights_only=True)
                svd = Decomposition(**saved)
            else:
                svd = decompose(weight, rank)
                if cache is not None:
                    cache.parent.mkdir(parents=True, exist_ok=True)
                    temp = cache.with_suffix(f".{uuid.uuid4().hex}.tmp")
                    torch.save(
                        {
                            "u": svd.u.cpu(),
                            "singular_values": svd.singular_values.cpu(),
                            "vh": svd.vh.cpu(),
                        },
                        temp,
                    )
                    temp.replace(cache)
        adapted = ModelLinear(
            weight,
            original.bias,
            rank=rank,
            rule=rule,
            initialization=initialization,
            gamma=gamma,
            seed=layer_seed(seed, name),
            decomposition=svd,
        )
        if rule != "additive" and (weight.norm(dim=1) <= adapted.norm_floor).any():
            raise ValueError(f"norm floor active: {name}")
        parent_name, leaf = name.rsplit(".", 1) if "." in name else ("", name)
        parent = model.get_submodule(parent_name) if parent_name else model
        setattr(parent, leaf, adapted)
        with torch.no_grad():
            error = (adapted.effective_weight() - weight).norm() / weight.norm()
        if error > 1e-5:
            raise ValueError(f"initial reconstruction failed: {name}")
        metadata[name] = {
            "weight_sha256": weight_hash,
            "shape": list(weight.shape),
            "relative_initial_error": float(error),
            "seed": layer_seed(seed, name),
        }
        if svd is not None:
            with torch.no_grad():
                expected = (gamma * svd.singular_values).sqrt()
                factor_errors = factor_spectrum_errors(adapted.B, adapted.A, expected)
            if max(factor_errors) > 1e-5:
                raise ValueError(
                    f"factor spectrum mismatch: {name}; condition={condition}; "
                    f"B_relative_error={factor_errors[0]:.6g}; "
                    f"A_relative_error={factor_errors[1]:.6g}; tolerance=1e-5; "
                    f"measurement=cpu_float64; decomposition={method}"
                )
            metadata[name]["factor_spectrum_relative_errors"] = factor_errors
            metadata[name]["spectrum_measurement"] = "cpu_float64"
            metadata[name]["svd_method"] = method
    for layer in model.modules():
        if isinstance(layer, nn.Dropout):
            layer.p = 0.0
        if hasattr(layer, "attention_dropout"):
            layer.attention_dropout = 0.0
    return {
        "layers": metadata,
        "trainable_parameters": sum(p.numel() for p in model.parameters() if p.requires_grad),
        "arithmetic": "dense FP32 targets; output cast to transformer dtype",
    }


def adapter_state(model) -> dict:
    return {
        name: layer.state_dict()
        for name, layer in model.named_modules()
        if isinstance(layer, ModelLinear)
    }


def restore_adapters(model, state: dict) -> None:
    names = {name for name, layer in model.named_modules() if isinstance(layer, ModelLinear)}
    if names != set(state):
        raise ValueError("checkpoint adapter targets differ")
    for name in names:
        model.get_submodule(name).load_state_dict(state[name])


def merge_adapters(model):
    """Only call on a separately loaded evaluation model; leaves training states intact."""
    for name, layer in list(model.named_modules()):
        if isinstance(layer, ModelLinear):
            # Keep FP32 target computation identical to the unmerged reference path.
            merged = FP32Linear(layer.merged_linear())
            parent_name, leaf = name.rsplit(".", 1) if "." in name else ("", name)
            setattr(model.get_submodule(parent_name) if parent_name else model, leaf, merged)
    return model


class FP32Linear(nn.Module):
    def __init__(self, linear):
        super().__init__()
        self.linear = linear

    def forward(self, inputs):
        with torch.autocast(device_type=inputs.device.type, enabled=False):
            output = self.linear(inputs.float())
        return output.to(inputs.dtype)


def load_model(root: Path, device: str, precision: str, attention: str):
    from transformers import AutoModelForCausalLM, AutoTokenizer

    if precision == "bf16" and device != "cuda":
        raise ValueError("Use fp32 for CPU checks; BF16 requires CUDA in this runner")
    if device == "cuda" and (
        not torch.cuda.is_available()
        or (precision == "bf16" and not torch.cuda.is_bf16_supported())
    ):
        raise RuntimeError("Requested CUDA/BF16 is unavailable")
    tokenizer = AutoTokenizer.from_pretrained(root / "model", local_files_only=True)
    tokenizer.pad_token = tokenizer.eos_token
    tokenizer.model_input_names = ["input_ids", "attention_mask"]
    model = AutoModelForCausalLM.from_pretrained(
        root / "model",
        local_files_only=True,
        dtype=torch.bfloat16 if precision == "bf16" else torch.float32,
        attn_implementation=attention,
    ).to(device)
    model.config.use_cache = False
    return model, tokenizer

initialization.py:
"""Balanced spectral and spectrum-matched random initialization."""

import math
from dataclasses import dataclass
from typing import Literal

import torch
from torch import Tensor

Initialization = Literal["spectral", "random"]


@dataclass(frozen=True)
class Decomposition:
    u: Tensor
    singular_values: Tensor
    vh: Tensor


@torch.no_grad()
def decompose(weight: Tensor, rank: int) -> Decomposition:
    """Compute the SVD once and reuse it across conditions."""
    if weight.ndim != 2 or not 1 <= rank <= min(weight.shape):
        raise ValueError("rank must be between 1 and min(weight.shape) for a matrix")
    if weight.dtype not in (torch.float32, torch.float64):
        raise ValueError("decompose in FP32, or FP64 for toy correctness checks")
    if not torch.isfinite(weight).all():
        raise ValueError("weight must be finite")
    # cuSOLVER's default Jacobi driver trades some precision for speed. Use the
    # QR-based driver for the study's strict spectrum/orthogonality checks.
    kwargs = {"driver": "gesvd"} if weight.device.type == "cuda" else {}
    u, values, vh = torch.linalg.svd(weight, full_matrices=False, **kwargs)
    return Decomposition(u[:, :rank], values[:rank], vh[:rank])


def _random_basis(rows: int, rank: int, template: Tensor, generator: torch.Generator) -> Tensor:
    noise = torch.randn(
        rows, rank, dtype=template.dtype, device=template.device, generator=generator
    )
    q, r = torch.linalg.qr(noise, mode="reduced")
    # Keep the QR diagonal signs consistent.
    signs = torch.where(r.diagonal() < 0, -1, 1)
    return q * signs


@torch.no_grad()
def initialize_factors(
    decomposition: Decomposition,
    initialization: Initialization,
    gamma: float,
    seed: int,
) -> tuple[Tensor, Tensor]:
    """Return B, A with factor spectra sqrt(gamma * sigma)."""
    if not math.isfinite(gamma) or gamma <= 0:
        raise ValueError("gamma must be finite and positive")
    u, values, vh = decomposition.u, decomposition.singular_values, decomposition.vh
    if initialization == "spectral":
        left, right = u, vh.T
    elif initialization == "random":
        generator = torch.Generator(device=u.device).manual_seed(seed)
        left = _random_basis(u.shape[0], values.numel(), u, generator)
        right = _random_basis(vh.shape[1], values.numel(), u, generator)
    else:
        raise ValueError(f"unknown initialization: {initialization}")
    scales = (gamma * values).sqrt()
    return (left * scales).clone(), (scales[:, None] * right.T).clone()

protocol.py:
"""Generate equal-budget searches, promotions, and frozen confirmation configs.

Writes job specifications only. Does not submit jobs or spend a GPU allocation.
"""

import argparse
import json
import math
from pathlib import Path

import yaml

from .experiment import RunConfig, config_dict, write_json
from .model import CONDITIONS


def grid(base: RunConfig) -> list[dict]:
    jobs = []
    for condition in CONDITIONS:
        if condition in ("L0", "D0"):
            candidates = [(1.0, 2e-6 * (1000 ** (i / 11))) for i in range(12)]
        else:
            candidates = [
                (gamma, rate) for gamma in (0.1, 0.3, 1.0) for rate in (2e-5, 1e-4, 5e-4, 2e-3)
            ]
        for index, (gamma, rate) in enumerate(candidates):
            config = config_dict(base)
            config.update(
                condition=condition, seed=10, gamma=gamma, learning_rate=rate, train_limit=None
            )
            jobs.append({"name": f"{condition}-{index:02d}", "config": config})
    return jobs


def ranked(summary):
    config = summary["config"]
    return (-summary["accuracy"], summary["answer_nll"], config["learning_rate"], config["gamma"])


def collect_screen(jobs: list[dict], runs: Path) -> list[dict]:
    results = []
    for job in jobs:
        summary = json.loads((runs / job["name"] / "screen" / "summary.json").read_text())
        if summary["config"] != job["config"] or summary["split"] != "dev":
            raise ValueError(f"screen config/split mismatch: {job['name']}")
        if (
            summary["count"] != 256
            or summary["nll_count"] < summary["count"]
            or summary["training_progress"]["epoch"] != 1
        ):
            raise ValueError("Screen each one-epoch checkpoint on 256 dev questions/full dev NLL")
        results.append({**job, "summary": summary})
    if len({r["summary"]["asset_hash"] for r in results}) != 1:
        raise ValueError("search candidates use different assets")
    return results


def promote(results: list[dict]) -> list[dict]:
    winners = []
    for condition in CONDITIONS:
        rows = [r for r in results if r["config"]["condition"] == condition]
        if condition in ("L0", "D0"):
            chosen = sorted(rows, key=lambda row: ranked(row["summary"]))[:3]
        else:
            chosen = [
                min(
                    [r for r in rows if r["config"]["gamma"] == gamma],
                    key=lambda row: ranked(row["summary"]),
                )
                for gamma in (0.1, 0.3, 1.0)
            ]
        winners.extend({"name": row["name"], "config": row["config"]} for row in chosen)
    return winners


def select(promoted: list[dict], runs: Path) -> dict:
    rows = []
    for job in promoted:
        summary = json.loads((runs / job["name"] / "final-dev" / "summary.json").read_text())
        if (
            summary["config"] != job["config"]
            or summary["split"] != "dev"
            or summary["count"] != summary["nll_count"]
            or summary["training_progress"]["epoch"] != job["config"]["epochs"]
        ):
            raise ValueError("Selection requires full-development scores at the fixed final epoch")
        rows.append({**job, "summary": summary})
    if len({r["summary"]["asset_hash"] for r in rows}) != 1:
        raise ValueError("different assets in selection")
    chosen, by_scale = {}, {}
    for condition in CONDITIONS:
        group = [r for r in rows if r["config"]["condition"] == condition]
        winner = min(group, key=lambda row: ranked(row["summary"]))
        chosen[condition] = winner["config"]
        if condition not in ("L0", "D0"):
            by_scale[condition] = {str(r["config"]["gamma"]): r["config"] for r in group}
    return {
        "asset_hash": rows[0]["summary"]["asset_hash"],
        "selected_configs": chosen,
        "fixed_scale_lr_winners": by_scale,
        "development_results": rows,
    }


def write_jobs(output: Path, jobs: list[dict]):
    if output.exists():
        raise FileExistsError("Use a new configuration directory")
    output.mkdir(parents=True)
    for job in jobs:
        (output / f"{job['name']}.yaml").write_text(yaml.safe_dump(job["config"], sort_keys=False))
    write_json(output / "jobs.json", jobs)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    search = sub.add_parser("search")
    search.add_argument("--base", type=Path, default=Path("configs/pilot.yaml"))
    promotion = sub.add_parser("promote")
    selection = sub.add_parser("select")
    for command in (promotion, selection):
        command.add_argument("--jobs", type=Path, required=True)
        command.add_argument("--runs", type=Path, default=Path("runs/search"))
    frozen = sub.add_parser("freeze")
    frozen.add_argument("--selection", type=Path, required=True)
    frozen.add_argument(
        "--margin",
        type=float,
        required=True,
        help="Prespecified practical margin in accuracy percentage points",
    )
    frozen.add_argument("--seeds", type=int, nargs="+", default=[101, 202, 303])
    for command in (search, promotion, selection, frozen):
        command.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.command == "search":
        base = RunConfig(**yaml.safe_load(args.base.read_text()))
        if base.epochs != 3:
            raise ValueError("The planned search requires a fixed three-epoch schedule")
        write_jobs(args.output, grid(base))
    elif args.command == "promote":
        jobs = json.loads(args.jobs.read_text())
        write_jobs(args.output, promote(collect_screen(jobs, args.runs)))
    elif args.command == "select":
        if args.output.exists():
            raise FileExistsError(args.output)
        write_json(args.output, select(json.loads(args.jobs.read_text()), args.runs))
    else:
        selected = json.loads(args.selection.read_text())
        if set(selected["selected_configs"]) != set(CONDITIONS):
            raise ValueError("Freeze all eight conditions")
        if not math.isfinite(args.margin) or args.margin <= 0:
            raise ValueError("margin must be finite and positive")
        if len(args.seeds) < 3 or len(set(args.seeds)) != len(args.seeds) or 10 in args.seeds:
            raise ValueError("Use at least three unique fresh confirmation seeds")
        configurations = {}
        jobs = []
        for condition, config in selected["selected_configs"].items():
            config = dict(config)
            config.pop("seed")
            configurations[condition] = config
            for seed in args.seeds:
                candidate = {**config, "seed": seed}
                RunConfig(**candidate)
                jobs.append({"name": f"{condition}-seed{seed}", "config": candidate})
        write_jobs(args.output, jobs)
        write_json(
            args.output / "frozen-protocol.json",
            {
                "asset_hash": selected["asset_hash"],
                "selected_configs": configurations,
                "confirmation_seeds": args.seeds,
                "practical_margin_points": args.margin,
                "parser": "last-#### exact Decimal; malformed/truncated = incorrect",
                "primary": "J",
                "secondary": "I",
            },
        )
